const request = $('Start').first().json._firstItem;
const filing = $('Start').first().json.Retrieve_File_Location__firstItem;

const text = $json.extracted_text || $json.text || '';

if (!text.trim()) {
  throw new Error('No usable PDF text was supplied.');
}

return [{
  json: {
    company_id: request.company_id,
    company_name: request.company_name,
    company_crn: request.company_crn,
    filing_id: filing.filing_id,
    financial_year: filing.financial_year,

    input_type: 'text',
    extracted_text: text,
    file_url: null,
    relevant_pages: [],

    extraction_method: 'native_pdf_text'
  }
}];
